import React from 'react';
import {Nav} from 'react-bootstrap';


const NavbarEmotes = (props) => {
	return (
    <Nav variant="tabs" defaultActiveKey={props.defaultActiveKey}>
      <Nav.Link href="#/emotes/top">Топ эмоций</Nav.Link>
      <br/><br/>
      <Nav.Link href="#/emotes/shared">Общие эмоции</Nav.Link>
      <br/><br/>
      <Nav.Link href="#/emotes/global">Глобальные эмоции</Nav.Link>
    </Nav>
	);
};

export default NavbarEmotes;