import React from 'react';
import { useParams } from 'react-router-dom';
import useFetch from "use-http"
import Loading from "../components/UI/Loading/Loading"
import useTitle from '../components/JS/Title'
import { decode } from '../lib/code-mnem'
import { Link } from 'react-router-dom';
import Moment from 'react-moment';
import User from "../components/UI/User/User"
import NotFound from "./NotFound"
import {HOSTURL} from "../index.js"


const Emotes = (props) => {
	const { id } = useParams();

	const {data, error} = useFetch(HOSTURL + "/api/v1/emote/" + id, {}, []);
	// console.log(data)

	const encoded = decode(data?.code)
	useTitle(`BetterWASD | Emote ${data?.code ? '| ' + encoded : ''}`, [data])
	if (error) return (<NotFound />);
	if (!data) return (<Loading />)

	let column = [
		{
			'marginRight': '10px',
			'justifyContent': 'flex-start'
		}, {
			'marginLeft': '10px'
		}, {
			'display': 'flex',
			'justifyContent': 'center'
		}, {
			'width': '32vw'
		}, {
			'display': 'flex',
			'justifyContent': 'space-evenly'
		}
	]
	let is = false
	if (!is) column = [{}, {}, {}, {'width': '64vw'}]

	return (
		<div style={column[2]}>
			<section className="d-flex-column" style={column[0]}>

				<div className="card block" style={column[3]}>
					<div className="card-header d-flex">
						<div style={{textTransform: 'none'}}>{encoded}</div>
						{data.global !== false ?
							<div>Глобальная эмоция</div>
							:
							<div>загружено <Link to={'/users/' + data.user.user_id}>{data.user.user_login}</Link> <Moment date={data.createdAt} format="DD.MM.YYYY" /> </div>
						}
					</div>
					<div className="card-body" style={{'display': 'flex', 'alignItems': 'center', 'justifyContent': 'center'}}>
						<img src={HOSTURL + "/cached/emote/" + data._id + "/1x"} alt="1x" />
						<img src={HOSTURL + "/cached/emote/" + data._id + "/2x"} alt="2x" />
						<img src={HOSTURL + "/cached/emote/" + data._id + "/3x"} alt="3x" />
					</div>
					{/*{data.global === false ?
						<div className="card-footer">
							<button className="blue button-small" disabled>Добавить на канал</button>
						</div>
						:
						""
					}*/}
				</div>

				{data.likes.total !== 0 ?
					<div className="card block" style={column[3]}>
						<div className="card-header d-flex">
							<div style={{textTransform: 'none'}}>Каналы ({data.likes.total})</div>
						</div>
						<div className="card-body">

							<div className="emotes">
								{ data && data.likes.users ? data.likes.users.map((user) => <User key={user.user_id} user={user}/>) : <Loading /> }
							</div>

						</div>
					</div>
					:
					""
				}


				{/* {data.message} */}
			</section>

			{
				is === true ? 
				<section className="d-flex-column" style={column[1]}>

					<div className="card block" style={column[3]}>
						<div className="card-header d-flex">
							<div style={{textTransform: 'none'}}>Настройка</div>
						</div>
						<div className="card-body">

							<div>Код эмоции</div>
							<input />
							<p>Коды эмоций могут быть буквами и цифрами. Он должен содержать не менее 1 заглавной буквы и не менее 5 символов.</p>

							<div>Примечания об утверждении</div>
							<textarea />
							<p>Если ваша эмоция будет решена для проверки вручную (либо автоматически, либо кем-то, кто сообщил об этом), пожалуйста, объясните эту эмоцию и предоставьте обоснование для использования.</p>

							<div>Совместное использование</div>
							<input />
							<p>Включение общего доступа позволяет другим пользователям добавлять эту эмоцию в свой чат WASD.TV.</p>

						</div>
						{data.global === false ?
							<div className="card-footer" style={column[4]}>
								<button className="blue button-small" disabled>Обновить эмоцию</button>
								<button className="blue button-small" disabled>Удалить эмоцию</button>
							</div>
							:
							""
						}
					</div>


					{/* {data.message} */}
				</section>
				:
				''
			}
		</div>
	);
};

export default Emotes;