import React, {useState, useEffect} from 'react';
import {useParams, useLocation, useNavigate, useSearchParams} from 'react-router-dom';
import useFetch from "use-http"
import Loading from "../components/UI/Loading/Loading"
import useTitle from '../components/JS/Title'
import Emote from "../components/UI/Emote/Emote"
import EmoteWithUsername from "../components/UI/Emote/EmoteWithUsername"
import NotFound from "./NotFound"
import {HOSTURL} from "../index.js"

import ReactPaginate from 'react-paginate'

const Emotes = (props) => {
	const { id } = useParams();
	const navigate = useNavigate()
	const location = useLocation()
	const [searchParams] = useSearchParams();
	const limit = 30*2
	const [page, setPage] = useState(0)

	const {data = [], loading, error, response} = useFetch(HOSTURL + "/api/v1/emote/user/" + id + "?limit=" +limit + "&offset=" + page*limit, {}, [page]);
	let total = response?.headers?.get('total')
	useTitle(`BetterWASD | User ${data?.user_login ? '| ' + data?.user_login : ''}`, [data])

	const pageChange = (e) => {
		setPage(e.selected)
		const to = { pathname: location.pathname, search: "?page="+(e.selected+1) };
		navigate(to, { replace: true });
	}

	useEffect(() => {
	  document.querySelector('.wrapper')?.scrollTo({top: 0, left: 0})
	}, [page])

	return (
		<section className="question-section" style={{paddingBottom: '160px'}}>
			{error && error.messge}
			{loading && <Loading />}
			{typeof data?.user_id != 'undefined' ? 
				<div className="items">
					<div className="item block item_right" style={{marginTop: '0px'}}>
						<div className="item__title"> Эмоции пользователя {data?.user_login} </div>
						<div className="item__descr"> Эмоции доступны на этом канале с BetterWASD. </div>
						<div className="item__border"></div>

						{data.channelEmotes.length ?
							<div>
								<div className="item__title"> Эмоции канала </div>
								<div className="emotes">
									{ data.channelEmotes.map((emote) => <Emote key={emote._id} emote={emote}/>) }
								</div>
							</div>
							:
							''
						}

						{data.sharedEmotes.length ?
							<div>
								<div className="item__title" style={{'marginTop': '25px'}}> Общие эмоции </div>
								<div className="emotes">
									{ data.sharedEmotes.map((emote) => <EmoteWithUsername key={emote._id} emote={emote}/>) }
								</div>
							</div>
							:
							''
						}

						{total > limit ? 
							<ReactPaginate
								pageCount={total/limit}
								marginPagesDisplayed={2}
								pageRangeDisplayed={5}
								nextLabel="Следующая"
								previousLabel="Предыдущая"
								onPageChange={pageChange}
								containerClassName={'pagination justify-content-center'}
								pageClassName={'page-item'}
								pageLinkClassName={'page-link'}
								previousClassName={'page-item'}
								previousLinkClassName={'page-link'}
								nextClassName={'page-item'}
								nextLinkClassName={'page-link'}
								breakClassName={'page-item'}
								breakLinkClassName={'page-link'}
								activeClassName={'active'}
								disabledClassName={'disabled'}
								initialPage={searchParams.get('page') ? Number(searchParams.get('page'))-1 : 0}
							/>
							:
							''
						}
					</div>
				</div>
				:
				<div className="items">
					<div className="emotes">
						{data?.message}
					</div>
				</div>
			}
		</section>
	);
};

export default Emotes;